 x *= 0x3DCE66D8EB3A5963ULL;
 if (((x >> 2) & 3ULL) == 2ULL) x ^= k + 0x3DCE66D8EB3A59C0ULL;
 x += k ^ 0x4BA3A9E31299F604ULL;
 x = (x << 52) | (x >> 12);
